(* [comment removed for export] *)
Lemma qS_mul Na Nb : 0 < Na -> 0 < Nb -> Na * Nb < 2 ^ 113 ->
  (Z.log2 (Na * Nb) = Z.log2 Na + Z.log2 Nb + 1 /\ qS Na * qS Nb = qS (Na * Nb) * 2 ^ 113)
