Definition exbit (x i n : Z) : Prop := exists d, 0 <= d < n /\ Z.testbit x (i + d) = true.

Lemma smear_step x y n : 0 < n ->
  (forall i, 0 <= i -> (Z.testbit y i = true <-> exbit x i n)) ->
  forall i, 0 <= i -> (Z.testbit (Z.lor y (Z.shiftr y n)) i = true <-> exbit x i (2 * n)).
Proof.
