Definition smear64 (x : Z) : Z :=
  let x1 := Z.lor x  (shr64 x 1) in
  let x2 := Z.lor x1 (shr64 x1 2) in
  let x3 := Z.lor x2 (shr64 x2 4) in
  let x4 := Z.lor x3 (shr64 x3 8) in
  let x5 := Z.lor x4 (shr64 x4 16) in
  Z.lor x5 (shr64 x5 32).

