Definition popc32_table_ok : bool :=
  forallb (fun k => Z.eqb (popc32 (not64 (Z.ones (k + 1)))) (31 - k)) (map Z.of_nat (seq 0 31)).
Lemma popc32_table : popc32_table_ok = true.
Proof.
