Lemma limbsA h l : 0 <= h < 2 ^ 48 -> 0 <= l < 2 ^ 64 ->
  let A1 := Z.lor (shr64 h 32) 0x10000 in let A2 := zext32 h in let A3 := shr64 l 32 in let A4 := zext32 l in
  (0 <= A1 < 2 ^ 17 /\ 0 <= A2 < 2 ^ 32 /\ 0 <= A3 < 2 ^ 32 /\ 0 <= A4 < 2 ^ 32)
  /\ A1 * 2 ^ 96 + A2 * 2 ^ 64 + A3 * 2 ^ 32 + A4 = (h + 2 ^ 48) * 2 ^ 64 + l.
Proof.
