Lemma limbsB h l : 0 <= h < 2 ^ 48 -> 0 <= l < 2 ^ 64 ->
  let bLo15 := shl64 l 15 in let bHi15 := Z.lor (shr64 l 49) (shl64 h 15) in
  let B1 := Z.lor (shr64 (shl64 h 15) 32) 0x80000000 in let B2 := zext32 bHi15 in let B3 := shr64 bLo15 32 in
  let B4 := zext32 bLo15 in
  (0 <= B1 < 2 ^ 32 /\ 0 <= B2 < 2 ^ 32 /\ 0 <= B3 < 2 ^ 32 /\ 0 <= B4 < 2 ^ 32)
