Lemma fix_hi_fields N E : qok N E ->
  let h := hi64 (qenc N E) in shr64 (shl64 h 1) 49 = qB N E /\ Z.lor (shr64 (shl64 h 16) 16) IMPLICIT_HI = qS N / 2 ^ 64
  /\ is_neg64 h = false.
