Lemma shl128_exact hi lo s : 0 <= hi < 2 ^ 64 -> 0 <= lo < 2 ^ 64 -> 0 <= s < 128 ->
  (hi * 2 ^ 64 + lo) * 2 ^ s < 2 ^ 128 ->
