Lemma addsub_sub_ok AHi ALo BHi BLo e :
  0 <= AHi < 2 ^ 64 -> 0 <= ALo < 2 ^ 64 -> 0 <= BHi < 2 ^ 64 -> 0 <= BLo < 2 ^ 64 ->
  let A := AHi * 2 ^ 64 + ALo in let B := BHi * 2 ^ 64 + BLo in
  B + 8 <= A -> A - B < 2 ^ 115 -> 113 <= e < 2 ^ 63 ->
  exists SHi SLo, addsub_mirror 1 AHi ALo BHi BLo e = Some (SHi, SLo, e - (115 - Z.log2 (A - B)))
    /\ SHi * 2 ^ 64 + SLo = (A - B) * 2 ^ (115 - Z.log2 (A - B)) /\ 0 <= SHi < 2 ^ 64 /\ 0 <= SLo < 2 ^ 64.
Proof.
