Lemma sigA_ok f l : 0 <= f < 2 ^ 48 -> 0 <= l < 2 ^ 64 ->
  let H := Z.lor (Z.lor (shl64 f 3) (shr64 l 61)) IMPL3_HI in let L := shl64 l 3 in
  H * 2 ^ 64 + L = ((f + 2 ^ 48) * 2 ^ 64 + l) * 8 /\ 0 <= H < 2 ^ 64 /\ 0 <= L < 2 ^ 64.
Proof.
