Definition dN (d : Z) : Z := let a := d mod 2 ^ 63 in if a / 2 ^ 52 =? 0 then a mod 2 ^ 52 else 2 ^ 52 + a mod 2 ^ 52.
Definition dE (d : Z) : Z := let a := d mod 2 ^ 63 in if a / 2 ^ 52 =? 0 then -1074 else a / 2 ^ 52 - 1075.

Lemma d_fields d : 0 <= d < 2 ^ 64 ->
  let aRep := lo64 d in
  shr64 (shl64 aRep 1) 53 = (d mod 2 ^ 63) / 2 ^ 52 /\ shr64 (shl64 aRep 12) 12 = d mod 2 ^ 52
  /\ shl64 (shr64 aRep 63) 63 = (d / 2 ^ 63) * 2 ^ 63 /\ 0 <= d / 2 ^ 63 <= 1.
Proof.
