Theorem f128_of_d_nonfinite_eq d : 0 <= d < 2 ^ 64 -> 2047 * 2 ^ 52 <= d mod 2 ^ 63 ->
  f128_of_d d = (d / 2 ^ 63 * 2 ^ 63 + 32767 * 2 ^ 48 + (d mod 2 ^ 52) / 2 ^ 4) * 2 ^ 64 + ((d mod 2 ^ 52) * 2 ^ 60) mod 2 ^ 64.
Proof.
