(* [comment removed for export] *)
Theorem prologue_zero d : 0 <= d < 2 ^ 64 -> d mod 2 ^ 63 = 0 ->
  let ya := mk128 (abs_hi (f128_of_d d)) (lo64 (f128_of_d d)) in
  ya = 0 /\ fpclassifyl_mirror (lo64 ya) (hi64 ya) = 2 /\ frexpl_ee (hi64 ya) = 0 /\ f128_le ya 0 = 0
  /\ f128_mul ya (f128_of_i32 2) = 0 /\ f128_le (f128_mul ya (f128_of_i32 2)) 0 = 0.
