Theorem prologue_nonfinite d : 0 <= d < 2 ^ 64 -> 2047 * 2 ^ 52 <= d mod 2 ^ 63 ->
  let ya := mk128 (abs_hi (f128_of_d d)) (lo64 (f128_of_d d)) in
  fpclassifyl_mirror (lo64 ya) (hi64 ya) <= 1.
