Ltac elim_mods := repeat match goal with |- context [?x mod 18446744073709551616] =>
    lazymatch x with context [_ mod 18446744073709551616] => fail | _ => idtac end;
    let k := fresh "k" in let H := fresh "Hm" in let R := fresh "Rm" in destruct (modW x) as (k & H & R); change (2 ^ 64) with 18446744073709551616 in H; rewrite H; clear H end.

