Lemma q1_core (A B Q : Z) : 0 <= A <= 2 ^ 30 -> 0 <= B < 2 ^ 64 ->
   Q * 2328306437 <= 4294967296 * A + B / 4294967296 < (Q + 1) * 2328306437 -> 0 <= Q ->
   let right := (2313682944 * Q) mod 2 ^ 64 in
   let t1 := (B + (18446744071395868672 * Q) mod 2 ^ 64) mod 2 ^ 64 in
   let t2 := (9999999997686317056 * Q) mod 2 ^ 64 in
   let b1 := if B <? right then 1 else 0 in
   let b2 := if t1 <? t2 then 1 else 0 in
   let mh := ((2328306436 * Q) mod 2 ^ 64) / 4294967296 in
   let A4 := (A + ((18446744073709551615 * b1) mod 2 ^ 64 + (((18446744073709551615 * b2) mod 2 ^ 64) + (18446744073709551615 * mh) mod 2 ^ 64) mod 2 ^ 64) mod 2 ^ 64) mod 2 ^ 64 in
   let A5 := (B + (8446744073709551616 * Q) mod 2 ^ 64) mod 2 ^ 64 in
   A4 * 2 ^ 64 + A5 = A * 2 ^ 64 + B - Q * 10000000000000000000 /\ 0 <= A4 < 2 ^ 64 /\ 0 <= A5 < 2 ^ 64 /\ Q < 2 ^ 31.
