(* [comment removed for export] *)
Lemma q2_step (A' B' : Z) : 0 <= A' < 2 ^ 64 -> 0 <= B' < 2 ^ 64 -> (A' <> 0 \/ 10000000000000000000 <= B') ->
  let A2 := (A' + (18446744073709551615 * (if B' <? 10000000000000000000 then 1 else 0)) mod 2 ^ 64) mod 2 ^ 64 in
  let B2 := (B' + 8446744073709551616) mod 2 ^ 64 in
