Lemma submul_core (v0 v1 q : Z) : 0 <= v0 < 2 ^ 64 -> 1 <= v1 <= 2 ^ 30 -> q = (v1 * 2 ^ 64 + v0) / 10000000000000000000 ->
   let lo := (10000000000000000000 * q) mod 2 ^ 64 in
   let c1 := if v0 <? lo then 1 else 0 in
   let c2 := if lo <? (2313682944 * q) mod 2 ^ 64 then 1 else 0 in
   let mh := (2328306436 * q) mod 2 ^ 64 / 4294967296 in
   let E64 := (v1 + ((18446744073709551615 * c1) mod 2 ^ 64 + ((18446744073709551615 * c2) mod 2 ^ 64 + (18446744073709551615 * mh) mod 2 ^ 64) mod 2 ^ 64) mod 2 ^ 64) mod 2 ^ 64 in
   let E56 := (v0 + (8446744073709551616 * q) mod 2 ^ 64) mod 2 ^ 64 in
   let T3 := (c1 + (c2 + mh) mod 2 ^ 64) mod 2 ^ 64 in
   E64 = 0 /\ E56 = (v1 * 2 ^ 64 + v0) mod 10000000000000000000 /\ T3 = v1 /\ 1 <= q < 2 ^ 31 /\ 0 <= E56 < 10000000000000000000.
